/**
 * NumPy Generator (PCG64) emulation for exact cross-implementation replay.
 *
 * The Python simulator draws exploration randomness from
 * `np.random.default_rng(seed)` (PCG64 + NumPy's Generator algorithms). For
 * the TypeScript port to replay the same episodes from the same seeds, it
 * must reproduce that stream bit-for-bit. This class does exactly that,
 * verified against frozen streams in `reference/rng-ref.json`
 * (generated by `skynerd/golden/rng_ref.py`).
 *
 * Reverse-engineered and verified empirically (see golden/rng_ref.py):
 * - 128-bit LCG state: S' = M·S + inc (mod 2^128),
 *   M = 0x2360ED051FC65DA44385DF649FCCF645
 * - XSL-RR 128/64 output: out = rotr64(hi ^ lo, top 6 bits of S)
 * - uniform() = (out >> 11) · 2^-53
 * - integers(n) for small n: Lemire's nearly-divisionless method over
 *   32-bit words; next_uint32 returns the LOW half of a uint64 first and
 *   caches the HIGH half (the cache survives uniform() calls untouched).
 *
 * BigInt is used for the 128-bit state; performance is irrelevant at the
 * decision timescale (a handful of draws per 0.2 s decision window).
 */

const MULTIPLIER = 0x2360ed051fc65da44385df649fccf645n;
const MOD_128 = 1n << 128n;
const MASK_64 = (1n << 64n) - 1n;
const TWO_53 = 9007199254740992; // 2^53
const TWO_32 = 4294967296;       // 2^32

export class NumpyPcg64 {
  private state: bigint;
  private readonly inc: bigint;
  private hasUint32 = false;
  private uinteger = 0;

  /**
   * @param state 128-bit LCG state (from `rng.bit_generator.state.state`)
   * @param inc   128-bit increment (from `rng.bit_generator.state.state.inc`)
   */
  constructor(state: bigint, inc: bigint) {
    this.state = state;
    this.inc = inc;
  }

  /** The multiplier constant, for reference tests. */
  static readonly MULTIPLIER = MULTIPLIER;

  /** One raw 64-bit draw — for spawning child streams deterministically
   *  (a live scene's per-drone dice; no existing consumer changes). */
  draw64(): bigint {
    return this.nextUint64();
  }

  private nextUint64(): bigint {
    this.state = (MULTIPLIER * this.state + this.inc) % MOD_128;
    const hi = this.state >> 64n;
    const lo = this.state & MASK_64;
    const rotation = Number(this.state >> 122n) & 63;
    let v = (hi ^ lo) & MASK_64;
    if (rotation !== 0) {
      v = (v >> BigInt(rotation)) | (v << BigInt(64 - rotation));
      v &= MASK_64;
    }
    return v;
  }

  /** numpy Generator.uniform() with default bounds. */
  uniform(): number {
    return Number(this.nextUint64() >> 11n) * (1.0 / TWO_53);
  }

  /** Returns the LOW 32 bits of a fresh uint64; caches the HIGH half. */
  private nextUint32(): number {
    if (this.hasUint32) {
      this.hasUint32 = false;
      return this.uinteger;
    }
    const v = this.nextUint64();
    this.uinteger = Number(v >> 32n);
    this.hasUint32 = true;
    return Number(v & 0xffffffffn);
  }

  /**
   * numpy Generator.integers(n) for 0 < n < 2^21 (the servo policy uses n=9).
   * Lemire's nearly-divisionless method on uint32 words: value = (w·n) >> 32,
   * rejected while low32(w·n) < 2^32 mod n. w·n must stay exact in f64,
   * hence the n < 2^21 guard.
   */
  integers(n: number): number {
    if (!Number.isInteger(n) || n <= 0 || n >= TWO_32 / 4096) {
      throw new Error(`integers(n) supports 0 < n < ${TWO_32 / 4096}; got ${n}`);
    }
    const threshold = TWO_32 % n;
    for (;;) {
      const word = this.nextUint32();
      const product = word * n;
      const low = product % TWO_32;
      if (low >= threshold) {
        return Math.floor(product / TWO_32);
      }
    }
  }

  /** Lemire bounded draw in [0, maxv] (inclusive) — numpy's
   * random_bounded_uint64 small-range path, as used by choice(). */
  private lemireInclusive(maxv: number): number {
    if (maxv <= 0) {
      return 0;
    }
    return this.lemire(maxv + 1);
  }

  private lemire(n: number): number {
    if (n <= 1) {
      return 0;
    }
    const threshold = TWO_32 % n;
    for (;;) {
      const word = this.nextUint32();
      const product = word * n;
      const low = product % TWO_32;
      if (low >= threshold) {
        return Math.floor(product / TWO_32);
      }
    }
  }

  /**
   * numpy Generator.permutation(n): Fisher-Yates over arange(n), i from
   * n-1 down to 1, j drawn in [0, i] by masked rejection on uint32 words
   * (random_interval). Verified against frozen streams.
   */
  permutation(n: number): number[] {
    const a = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i >= 1; i--) {
      let mask = i;
      mask |= mask >> 1; mask |= mask >> 2; mask |= mask >> 4;
      mask |= mask >> 8; mask |= mask >> 16;
      let j: number;
      do {
        j = this.nextUint32() & mask;
      } while (j > i);
      const tmp = a[i];
      a[i] = a[j];
      a[j] = tmp;
    }
    return a;
  }

  /**
   * numpy Generator.choice(n, size=k, replace=False) — the flock's donor
   * and key selection. Floyd's algorithm over a linear-probing hash set,
   * then a Fisher-Yates shuffle of the k samples (shuffle=True default).
   * Both bounded draws are Lemire-inclusive over uint32 words.
   */
  choice(n: number, k: number): number[] {
    if (k > n) {
      throw new Error("cannot sample more than the population");
    }
    const EMPTY = -1;
    const setWanted = Math.trunc(1.2 * k);
    let mask = setWanted;
    mask |= mask >> 1; mask |= mask >> 2; mask |= mask >> 4;
    mask |= mask >> 8; mask |= mask >> 16; mask |= mask >> 32;
    const table = new Float64Array(1 + mask).fill(EMPTY); // key slots (values < 2^53)
    const idx = new Array<number>(k).fill(0);
    for (let j = n - k; j < n; j++) {
      const val = this.lemireInclusive(j);
      let loc = val & mask;
      while (table[loc] !== EMPTY && table[loc] !== val) {
        loc = (loc + 1) & mask;
      }
      if (table[loc] === EMPTY) {
        table[loc] = val;
        idx[j - (n - k)] = val;
      } else {
        loc = j & mask;
        while (table[loc] !== EMPTY) {
          loc = (loc + 1) & mask;
        }
        table[loc] = j;
        idx[j - (n - k)] = j;
      }
    }
    for (let i = k - 1; i >= 1; i--) {
      const j = this.lemireInclusive(i);
      const tmp = idx[i];
      idx[i] = idx[j];
      idx[j] = tmp;
    }
    return idx;
  }
}
